976	  const m = /^([\d.]+)\s*([KMGT]?)/i.exec(clean(label, 32));
977	  if (!m) return 0;
978	  const mult: Record<string, number> = { "": 1, K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };
979	  return Math.max(0, Math.round(parseFloat(m[1]) * (mult[m[2].toUpperCase()] ?? 1)));
