984	  const u = ["B", "KB", "MB", "GB", "TB"];
985	  let i = 0;
986	  let v = n;
987	  while (v >= 1024 && i < u.length - 1) {
988	    v /= 1024;
989	    i++;
990	  }
991	  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${u[i]}`;
