  if (!validImageRef(ref)) return { status: "failed", detail: "image reference failed validation" };

  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
    return { status: "present", detail: "already on the new server" };
  }

  if (!local) {
    // A multi-gigabyte pull is one of the three steps that can sit silent for
    // minutes, so it narrates itself (see withHeartbeat).
    const pull = await withHeartbeat(`downloading the container image ${ref}`, say, () =>
      sh(conn, `docker pull ${ref} 2>&1`, IMAGE_TIMEOUT_MS)
    );
    if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
      return { status: "pulled", detail: "pulled from its registry" };
