  // through the SSH channel we already hold. gzip -1 because these links are
  // usually faster than the CPU and the layers are mostly already compressed.
  const stream = `${onSource(`${priv}docker save ${ref} | gzip -1`)} | gunzip -c | docker load 2>&1`;
  const r = await withHeartbeat(`transferring the container image ${ref} from the old server`, say, () =>
    sh(conn, stream, IMAGE_TIMEOUT_MS)
